package com.mediconnect.controller;
import com.mediconnect.dto.ApiDtos;import com.mediconnect.entity.*;import com.mediconnect.repository.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/prescriptions")
public class PrescriptionController{
 private final PrescriptionRepository repo;private final UserRepository users;private final AppointmentRepository appointments;
 public PrescriptionController(PrescriptionRepository r,UserRepository u,AppointmentRepository a){repo=r;users=u;appointments=a;}
 @GetMapping public List<ApiDtos.PrescriptionView> list(@AuthenticationPrincipal User u){if(u.getRole()==Role.PLATFORM_SUPER_ADMIN)throw forbidden("Platform administrators do not have clinical record access");List<Prescription>x=switch(u.getRole()){case ADMIN->repo.findByHospitalIdOrderByCreatedAtDesc(hospitalId(u));case DOCTOR->repo.findByDoctorIdOrderByCreatedAtDesc(u.getId());case PATIENT->repo.findByPatientIdOrderByCreatedAtDesc(u.getId());case PLATFORM_SUPER_ADMIN->List.of();};return x.stream().map(ApiDtos.PrescriptionView::of).toList();}
 @PostMapping @PreAuthorize("hasRole('DOCTOR')") public ApiDtos.PrescriptionView create(@AuthenticationPrincipal User doctor,@RequestBody Map<String,Object>b){Long pid=id(b.get("patientId")),aid=id(b.get("appointmentId"));if(pid==null||aid==null||s(b,"medicine").isBlank())throw bad("Patient, completed appointment and medicine are required");User p=users.findById(pid).orElseThrow(()->notFound("Patient not found"));if(p.getRole()!=Role.PATIENT||!sameHospital(doctor,p))throw bad("Patient is unavailable in this hospital");Appointment a=appointments.findById(aid).orElseThrow(()->notFound("Appointment not found"));if(!a.getDoctor().getId().equals(doctor.getId())||!a.getPatient().getId().equals(pid)||!sameHospital(doctor,a.getHospital()))throw forbidden("Appointment does not belong to this consultation");if(a.getStatus()!=AppointmentStatus.COMPLETED)throw bad("Prescriptions require a completed appointment");Prescription x=new Prescription();x.setHospital(doctor.getHospital());x.setPatient(p);x.setDoctor(doctor);x.setAppointment(a);x.setMedicine(s(b,"medicine"));x.setDosage(s(b,"dosage"));x.setFrequency(s(b,"frequency"));x.setDuration(s(b,"duration"));x.setInstructions(s(b,"instructions"));return ApiDtos.PrescriptionView.of(repo.save(x));}
 private static boolean sameHospital(User a,User b){return a.getHospital()!=null&&b.getHospital()!=null&&a.getHospital().getId().equals(b.getHospital().getId());}private static boolean sameHospital(User u,Hospital h){return u.getHospital()!=null&&h!=null&&u.getHospital().getId().equals(h.getId());}private static Long hospitalId(User u){if(u.getHospital()==null)throw forbidden("Hospital membership required");return u.getHospital().getId();}private static Long id(Object o){try{return o==null?null:Long.valueOf(String.valueOf(o));}catch(Exception e){return null;}}private static String s(Map<String,Object>b,String k){return b.get(k)==null?"":String.valueOf(b.get(k)).trim();}private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}private static ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}
}
